def-hyp[predicate](
    Type.annotation(@x, S@Topology.ctxt.S), 
    Topology.neighborhoodBasis(x),
    Logic.forall-typed(
        @U, 
        Set(S@Topology.ctxt.S),
        Logic.implies(
            Set.mem(U, Topology.Nbr(x)),
            Logic.exists-typed(
                @V, 
                Set(S@Topology.ctxt.S),
                Logic.and(Set.mem(V, Topology.neighborhoodBasis(x)), Set.subset(V, U))
            )
        )
    )
)
